<script setup>
import ChevronText from './ChevronText.vue';
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue';
import {router} from '@inertiajs/vue3';
import StudySummary from './StudySummary.vue';
import Errors from './Errors.vue';
import {useI18n} from '../lib/i18n.js';
import {memberQuery,memberActionData,previewMemberAction} from '../lib/member-management.js';
const props=defineProps({members:{type:Object,default:()=>({data:[],current_page:1,last_page:1,total:0})},filters:{type:Object,default:()=>({q:''})},selectedMember:{type:Object,default:null}});
const emit=defineEmits(['busy']);const {t}=useI18n();
const query=ref(props.filters.q??''),busy=ref(false),errors=ref({}),scope=ref('selected'),heading=ref(null),searchInput=ref(null),unavailable=ref(false),notice=ref('');
let generation=0,controller=null,phase='',returnId=null,returnScroll=null;const buttons=new Map();
const collectionIndex=computed(()=>props.selectedMember?.collections.findIndex(item=>Number(item.id)===Number(props.selectedMember.selected_collection_id))??-1);
const selectedCollection=computed(()=>props.selectedMember?.collections[collectionIndex.value]??null);
watch(()=>props.filters.q,value=>{query.value=value??'';});watch(()=>[props.selectedMember?.id,props.selectedMember?.selected_collection_id],()=>{scope.value='selected';if(phase==='preview'){generation++;controller?.abort();busy.value=false;phase='';}});watch(busy,value=>emit('busy',value));
onBeforeUnmount(()=>{generation++;controller?.abort();emit('busy',false);});
function queryData(extra={}){return memberQuery({q:props.filters.q,page:props.members.current_page},extra);}
async function focusList(){await nextTick();if(props.selectedMember)return;(buttons.get(returnId)??searchInput.value)?.focus({preventScroll:true});if(returnScroll!==null)window.scrollTo({top:returnScroll,behavior:'instant'});}
function visit(data,focus='none'){
 if(busy.value)return;busy.value=true;phase='visit';errors.value={};unavailable.value=false;const request=++generation;
 router.get('/collections',data,{preserveState:true,preserveScroll:true,onError:value=>{if(request===generation)errors.value=value;},onSuccess:async()=>{if(request!==generation)return;await nextTick();if(focus==='member'){if(props.selectedMember){heading.value?.focus({preventScroll:true});heading.value?.scrollIntoView({block:'start',behavior:'instant'});}else{unavailable.value=true;await focusList();}}else if(focus==='list')await focusList();},onFinish:()=>{if(request===generation)busy.value=false;}});
}
function search(){query.value=query.value.trim();visit(memberQuery({q:query.value,page:1}));}
function openMember(person){returnId=person.id;returnScroll=window.scrollY;visit(queryData({member:person.id}),'member');}
function closeMember(){visit(queryData(),'list');}
function chooseCollection(id){if(!props.selectedMember?.collections.some(item=>item.id===Number(id)))return;visit(queryData({member:props.selectedMember.id,member_collection:Number(id)}));}
function moveCollection(offset){const target=props.selectedMember?.collections[collectionIndex.value+offset];if(target)chooseCollection(target.id);}
function registerButton(id,element){if(element)buttons.set(id,element);else buttons.delete(id);}
function confirmation(action,preview,person,collection){
 const target=preview.scope==='all'?t(action==='block'?'all collections you currently own, including those this account has not joined':action==='remove'?'all current memberships in collections you own':'all current blocks in collections you own'):t('the selected collection “{title}”',{title:collection.title});
 const detail=action==='remove'?t('Removal keeps private notes and history. Joining again requires fresh consent, which may share past progress again.'):action==='block'?t('Blocking removes membership and prevents this account from rejoining. Guest links can still be viewed while signed out.'):t('Unblocking allows a new join with fresh consent; it does not restore membership.');
 return t('{action} {name} in {count} collection(s): {scope}?',{action:t(action==='remove'?'Remove member':action==='block'?'Block account':'Unblock account'),name:person.name,count:preview.count,scope:target})+'\n\n'+detail;
}
async function manage(action){
 if(busy.value||!props.selectedMember||!selectedCollection.value)return;
 const person=props.selectedMember,collection=selectedCollection.value,data=memberActionData(action,scope.value,collection.id);busy.value=true;phase='preview';errors.value={};notice.value='';const request=++generation;controller=new AbortController();
 try{const preview=await previewMemberAction(person.id,data,{signal:controller.signal});if(request!==generation)return;if(!window.confirm(confirmation(action,preview,person,collection))){busy.value=false;return;}
 phase='apply';router.post(`/collection-members/${person.id}/apply`,{...data,token:preview.token,member_q:props.filters.q??'',members_page:props.members.current_page,member_collection:collection.id},{preserveScroll:true,onSuccess:async()=>{if(request!==generation)return;notice.value=t('Member access updated.');if(!props.selectedMember)await focusList();else if(!selectedCollection.value){await nextTick();heading.value?.focus({preventScroll:true});}},onError:value=>{if(request===generation)errors.value=value;},onFinish:()=>{if(request===generation)busy.value=false;}});
 }catch(error){if(request!==generation||error.name==='AbortError')return;errors.value={members:t(['Your sign-in session expired. Keep this page open and sign in in another tab, then retry.','No eligible collections are available for this action.'].includes(error.message)?error.message:'Member access changed or the request failed. Refresh the member list and try again.')};busy.value=false;}
}
</script>
<template><div class="collection-members" :aria-busy="busy"><Errors :errors="errors"/><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="unavailable" role="status" class="notice">{{t('This member is no longer available in your collections.')}}</p><p v-if="busy" role="status" class="muted">{{t('Loading…')}}</p>
<template v-if="!selectedMember"><form class="panel members-search" @submit.prevent="search"><label>{{t('Search accounts by name or email')}}<input ref="searchInput" v-model="query" type="search" maxlength="100" :disabled="busy"/></label><button class="button" :disabled="busy">{{t('Search')}}</button><button v-if="query" type="button" class="button secondary" :disabled="busy" @click="query='';search()">{{t('Clear search')}}</button></form><section class="panel"><h2>{{t('Members ({count})',{count:members.total})}}</h2><p class="muted small">{{t('Each person appears once across collections you own. Email search requires current progress-sharing consent.')}}</p><p v-if="!members.data.length" class="muted">{{t(query?'No accounts match your search.':'No members or blocked accounts in your collections yet.')}}</p><table v-if="members.data.length" class="members-table"><caption class="sr-only">{{t('Members ({count})',{count:members.total})}}</caption><thead><tr><th scope="col">{{t('Member name')}}</th><th scope="col" class="member-action-cell">{{t('Action')}}</th></tr></thead><tbody><tr v-for="person in members.data" :key="person.id"><th scope="row" class="member-name-cell"><bdi dir="auto">{{person.name}}</bdi></th><td class="member-action-cell"><button :ref="el=>registerButton(person.id,el)" type="button" class="button secondary" :aria-label="t('View {name}',{name:person.name})" :disabled="busy" @click="openMember(person)">{{t('View')}}</button></td></tr></tbody></table><nav v-if="members.last_page>1" class="members-pagination" :aria-label="t('Member pages')"><button class="button secondary" :disabled="busy||members.current_page<=1" @click="visit(memberQuery({q:filters.q,page:members.current_page-1}))"><ChevronText :text="t('← Previous')"/></button><span>{{t('Page {page} of {total}',{page:members.current_page,total:members.last_page})}}</span><button class="button secondary" :disabled="busy||members.current_page>=members.last_page" @click="visit(memberQuery({q:filters.q,page:members.current_page+1}))"><ChevronText :text="t('Next →')"/></button></nav></section></template>
<section v-else class="panel member-detail"><div class="section-heading"><h2 ref="heading" tabindex="-1">{{selectedMember.name}}</h2><button class="button secondary" :disabled="busy" @click="closeMember">{{t('Back to members')}}</button></div><div v-if="selectedMember.collections.length" class="member-collection-picker"><button type="button" class="button secondary" :aria-label="t('Previous collection')" :disabled="busy||collectionIndex<=0" @click="moveCollection(-1)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true" focusable="false"><path d="m15 6-6 6 6 6"/></svg></button><label>{{t('Collection')}}<select :value="selectedMember.selected_collection_id" :disabled="busy" @change="chooseCollection($event.target.value)"><option v-if="!selectedCollection" :value="null" disabled>{{t('Choose a collection')}}</option><option v-for="collection in selectedMember.collections" :key="collection.id" :value="collection.id">{{collection.title}}</option></select></label><button type="button" class="button secondary" :aria-label="t('Next collection')" :disabled="busy||collectionIndex>=selectedMember.collections.length-1" @click="moveCollection(1)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true" focusable="false"><path d="m9 6 6 6-6 6"/></svg></button></div><p v-else class="notice">{{t('This member is no longer available in your collections.')}}</p>
<p v-if="selectedMember.collections.length&&!selectedCollection" class="notice">{{t('Choose a collection to view this member’s progress.')}}</p><template v-if="selectedCollection"><p class="pill">{{t(selectedCollection.blocked?'Blocked account':selectedCollection.is_member?'Current member':'Not a current member')}}</p><StudySummary v-if="selectedCollection.can_view_progress&&selectedMember.summary" :summary="selectedMember.summary" :base="`/collections/${selectedCollection.id}`" read-only/><p v-else class="notice">{{t('Progress unavailable. Current sharing consent and an active account are required.')}}</p><p class="muted small">{{t('Only consented progress for this collection is shown. Personal notes are never shown.')}}</p><section class="member-access"><h3>{{t('Manage access')}}</h3><label>{{t('Action scope')}}<select v-model="scope" :disabled="busy"><option value="selected">{{t('Selected collection only')}}</option><option value="all">{{t('All eligible collections I own')}}</option></select></label><p v-if="scope==='all'" class="notice">{{t('All scope: remove current memberships, block all currently owned collections including those not joined, or unblock current blocks. Already blocked collections are not counted again.')}}</p><p class="muted small">{{t('The confirmation shows the exact number of affected collections. A changed scope must be reviewed again.')}}</p><div class="member-access-buttons"><button class="button secondary" :disabled="busy||(scope==='selected'&&!selectedCollection.is_member)" @click="manage('remove')">{{t('Remove member')}}</button><button class="button secondary" :disabled="busy||(scope==='selected'&&selectedCollection.blocked)" @click="manage('block')">{{t('Block account')}}</button><button class="button secondary" :disabled="busy||(scope==='selected'&&!selectedCollection.blocked)" @click="manage('unblock')">{{t('Unblock account')}}</button></div><p class="notice">{{t('Guest links do not identify signed-out visitors. Blocking an account cannot prevent signed-out viewing while guest access is enabled.')}}</p></section></template></section></div></template>
<style scoped>
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.collection-members{display:grid;gap:20px;min-width:0}.members-search{display:flex;align-items:end;gap:12px}.members-search label{flex:1;margin:0;min-width:0}.members-table{width:100%;table-layout:fixed;border-collapse:collapse;margin:20px 0}.members-table th,.members-table td{padding:14px 8px;border-bottom:1px solid #dce5e4;text-align:left;vertical-align:middle}.members-table thead th{font-size:12px;color:var(--muted)}.members-table .member-name-cell{overflow-wrap:anywhere;font-weight:650;background:transparent;color:var(--navy);font-size:14px;text-transform:none;letter-spacing:normal}.members-table .member-action-cell{width:152px;text-align:right}.member-action-cell .button{min-width:112px;max-width:100%;white-space:nowrap;padding:12px 16px}.member-detail h2{overflow-wrap:anywhere;min-width:0}.member-collection-picker>button{flex:0 0 44px;min-width:44px;padding:10px}.member-collection-picker svg{flex-shrink:0}.members-pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.member-collection-picker{display:flex;align-items:end;gap:12px;margin:20px 0}.member-collection-picker label{flex:1;min-width:0;margin:0}.member-collection-picker select{width:100%}.member-access{border-top:1px solid #dce5e4;padding-top:20px;margin-top:20px}.member-access-buttons{display:flex;gap:12px;flex-wrap:wrap}.member-access-buttons .button{flex:1;white-space:normal}.collection-members button{min-height:44px}.member-detail .section-heading{flex-wrap:wrap;gap:12px}.member-detail h2:focus-visible{outline:3px solid var(--teal);outline-offset:4px}.member-detail :deep(.study-history){margin-top:24px}.member-detail :deep(.mode-grid){grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr))}@media(max-width:760px){.members-search{flex-direction:column;align-items:stretch}.members-search button,.member-access-buttons button{width:100%}.members-table th,.members-table td{padding:12px 4px}.members-table .member-action-cell{width:128px}.member-access-buttons{flex-direction:column}.member-detail{padding:16px}.member-collection-picker{gap:8px}.member-collection-picker>button{padding:10px}.members-pagination>button{flex:1}.members-pagination span{flex-basis:100%;text-align:center;order:-1}}
</style>
